-- migra-135 (10/10/2026): el aura no baja, por el decaimiento diario, de ningun numero entero que la persona haya alcanzado (6, 7, 8…),
-- para que el tiempo sin entrar no desanime. users.aura_suelo guarda ese mayor entero; lib/aura.php lo sube al sumar aura y lo respeta
-- en aura_daily_decay() (el suelo efectivo es el mayor de aura_start y aura_suelo). Usar aura (destacar) sigue pudiendo bajar hasta
-- aura_gasto_minimo. Y se explica en «¿Que es Deltha?» (Aura), «Como funciona el δ» (Aura) y «Como empezar» (Aura) en los nueve idiomas:
-- una frase añadida con REPLACE tras la que habla del decaimiento; si ese parrafo se edito en admin -> Paginas, ese idioma no cambia.
SET NAMES utf8mb4;
ALTER TABLE users ADD COLUMN aura_suelo DECIMAL(8,3) NOT NULL DEFAULT 0 AFTER aura;
UPDATE users SET aura_suelo = FLOOR(aura);

UPDATE pages SET body = REPLACE(body, 'hasta el mínimo de {aurastart}.', 'hasta el mínimo de {aurastart}. Pero cada número entero que alcanzas (6, 7, 8…) se queda como tu mínimo: el tiempo sin entrar no te baja de ahí.') WHERE slug = 'que-es';
